/**
 ******************************************************************************
 * @file    tony_debug.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 28 Oct 2026 for Tony's display task; the FxRenderTask stack row, the effect-file job row and the crossover hint on 30 Oct 2026, with an AI coding assistant.
 * @brief   Hidden TFT debug screen (Tony Le): page actions and renderer.
 *
 * RTOS role: no task of its own. It runs inside TonyTask and only tony_ui.c
 * calls it. Hold BACK (PB0) for 2 s on Home to open it (debug_menu.c spots
 * the hold, ui_enter_debug() opens it); a short BACK closes it. This screen
 * is where the diagnostics and tests are (the serial console was removed on
 * 1 Nov 2026).
 *
 * The encoder walks five pages: System, Storage, Battery / power (one
 * position each, so every detent changes page), then the Speaker test and
 * Fault injection lists (item by item). Every number shown comes from a
 * message or an RTOS counter, never from another task's peripheral
 * (lecture 07 owner-task rule):
 *   System         App_RTOS_GetStats(): RTOS counters and handles only,
 *                  the stacks of all six tasks (FxRenderTask too)
 *   Storage        Jack's StorageStatusMsg_t (tony_ui.c's copy, refreshed by
 *                  a STORAGE_REQ_STATUS once a second while on that page),
 *                  with the effect file being made now ("FX job")
 *   Battery/power  BrendonTask's PowerDebugMsg_t (powerDebugQueue, 1 Hz),
 *                  plus the currents and time estimates of his BatteryMsg_t
 *                  (tony_ui.c's copy in ui_state_t)
 * and every action is a message:
 *   Speaker        TomCmd_t TEST_PATTERN / PLAY_TUNE / STOP (tomCmdQueue)
 *   Faults         BrendonCmd_t SOC override (brendonCmdQueue), or a
 *                  simulated FaultMsg_t raised by TonyTask itself
 *
 * Drawing: the 6 x 8 px font at size 1 gives 40 characters per row on the
 * 240 px wide portrait panel; rows every 16 px from y = 4, 20 at most (the
 * last ends at y 315). The whole page is drawn when the screen opens, after
 * a fault overlay and on a page change (~0.45 s; a fault arriving meanwhile
 * stops it, see emit_row). After that a pass once a second (and straight
 * after a cursor step or an action) rebuilds the text of every row but only
 * sends the rows that changed to the panel: a 32-bit hash per row (80 B)
 * remembers what each row shows, so no copy of the screen text is kept.
 * Everything is static: TonyTask's 3 KB stack already carries the ILI9341
 * driver's 500 B burst buffer (docs/RTOS_ARCHITECTURE.md section 6 has the
 * stack estimate).
 ******************************************************************************/
#include "tony_debug.h"
#include "app_rtos.h"
#include "ILI9341_STM32_Driver.h"
#include "ILI9341_GFX.h"
#include "ui_types.h"
#include "debug_menu.h"
#include "display_logic.h"      /* ui_format_hhmm(): hh:mm like the Battery screen */
/* Other members' headers for their numbering only (types and defines, no
 * calls): */
#include "tom_dac_output.h"     /* Tom_Test_t: the Speaker page's test patterns */
#include "storage_port.h"       /* storage_result_t: StorageStatusMsg_t.last_result */
#include "charger_status.h"     /* Charger_State: PowerDebugMsg_t.charger_state */
#include "usbd_def.h"           /* USBD_STATE_*: PowerDebugMsg_t.usb_state */
#include <stdarg.h>
#include <stdio.h>
#include <string.h>

/* -------------------------------------------------------------------------- */
/* Layout / timing                                                            */
/* -------------------------------------------------------------------------- */
#define DBG_COLS            (SCREEN_W / 6U)     /* 40: 240 px / 6 px per size-1 character */
#define DBG_ROWS            20U     /* y = 4 + 16 x 19 = 308: the last row ends at y 315 */
#define DBG_X               ((SCREEN_W - DBG_COLS * 6U) / 2U)   /* 0: 40 x 6 = 240 px, the whole width */
#define DBG_Y0              4U
#define DBG_DY              16U
#define DBG_REFRESH_MS      1000U   /* the pages update once a second */
#define DBG_STALE_MS        3000U   /* no PowerDebugMsg_t for this long: say so */
#define DBG_LOW_STACK_B     200U    /* stack rows turn red below this (the prompt's limit) */
#define DBG_NONE            DEBUG_INDEX_NONE   /* no pattern playing / no tune sent / nothing injected */

#define DBG_TITLE_COLOUR    CYAN
#define DBG_TEXT_COLOUR     WHITE
#define DBG_CURSOR_COLOUR   YELLOW      /* the cursor row, and a debug SOC override in force */
#define DBG_HINT_COLOUR     LIGHTGREY
#define DBG_OK_COLOUR       GREENYELLOW
#define DBG_LOW_COLOUR      ORANGE      /* battery LOW alarm */
#define DBG_WARN_COLOUR     RED

/* debug_menu.c numbers the Speaker items in Tom's order (patterns from
 * TOM_TEST_SWEEP_100 to TOM_TEST_RIGHT_ONLY, then the TomTune_t tunes); the
 * build stops here if either side changes. */
_Static_assert((int)TOM_TEST_SWEEP_100 + (int)DEBUG_SPEAKER_PATTERNS - 1 == (int)TOM_TEST_RIGHT_ONLY,
               "Speaker page patterns must match Tom_Test_t");
_Static_assert((int)DEBUG_SPEAKER_TUNES == (int)TOM_TUNE_COUNT,
               "Speaker page tunes must match TomTune_t");
/* Every row, 8 px of text each, must be on the panel: rows past the bottom
 * would be clipped by the driver without a word. */
_Static_assert(DBG_Y0 + (DBG_ROWS - 1U) * DBG_DY + 8U <= SCREEN_H, "debug rows off screen");

/* -------------------------------------------------------------------------- */
/* State                                                                       */
/* -------------------------------------------------------------------------- */
/* Rows: the one being built and a hash of what each row shows now. */
static char     s_row[DBG_COLS + 1U];
static uint32_t s_row_hash[DBG_ROWS];
static uint8_t  s_row_n;                    /* rows emitted so far in this pass */
static uint8_t  s_full;                     /* this pass follows a full-screen fill */
static uint8_t  s_abort;                    /* a fault is waiting: this whole-page draw stops */

/* When to draw: the page and cursor the last pass drew (0xFF = none yet),
 * an action that changed the text, and the next 1 Hz pass. */
static uint8_t  s_drawn_page = 0xFFU;
static uint8_t  s_drawn_item = 0xFFU;
static uint8_t  s_dirty = 0U;
static uint32_t s_next_pass_ms = 0U;

/* Data for the pages (static: ~140 B kept off TonyTask's stack). */
static AppRtosStats_t  s_stats;             /* System page, refilled on every pass */
static PowerDebugMsg_t s_pwr;               /* BrendonTask's newest snapshot ... */
static uint8_t         s_pwr_valid = 0U;    /* ... 0 until the first one arrives */
static uint32_t        s_pwr_rx_ms = 0U;

/* What the actions did, shown on their pages. */
static uint8_t  s_pattern_item = DBG_NONE;  /* Speaker item whose test pattern is playing */
static uint8_t  s_tune_item = DBG_NONE;     /* Speaker item of the last tune sent */
static uint8_t  s_sent_item = DBG_NONE;     /* Faults item injected last ... */
static uint8_t  s_sent_ok = 0U;             /* ... and whether its message went out */

/* -------------------------------------------------------------------------- */
/* Names for the numbers in the messages                                       */
/* -------------------------------------------------------------------------- */
static const char *const s_storage_results[] = {
    [STORAGE_OK]          = "none",
    [STORAGE_WRITE_FAIL]  = "write failed",
    [STORAGE_READ_FAIL]   = "read failed",
    [STORAGE_SLOW]        = "card too slow",
    [STORAGE_FULL]        = "card full",
    [STORAGE_NOT_FOUND]   = "not found",
    [STORAGE_CORRUPT]     = "corrupt file / no FAT",
    [STORAGE_TRUNCATED]   = "file list cut short",
    [STORAGE_INVALID_ARG] = "invalid argument",
    [STORAGE_REFUSED]     = "refused",              /* Jack's DELETE and effect files (30 Oct 2026) */
    [STORAGE_NO_SLOT]     = "no lock slot",
};

static const char *const s_charger_states[] = {
    [CHARGER_STATE_UNKNOWN]              = "unknown",
    [CHARGER_STATE_NO_INPUT]             = "no input",
    [CHARGER_STATE_CHARGING]             = "charging",
    [CHARGER_STATE_COMPLETE_OR_DISABLED] = "complete / off",
    [CHARGER_STATE_FAULT]                = "FAULT (STAT blinks)",
};

static const char *const s_usb_states[] = {
    [USBD_STATE_DEFAULT]    = "default",
    [USBD_STATE_ADDRESSED]  = "addressed",
    [USBD_STATE_CONFIGURED] = "configured",
    [USBD_STATE_SUSPENDED]  = "suspended",
};

/* A name from one of the tables above; "?" for a number it does not know. */
static const char *table_name(const char *const *table, size_t count, uint32_t v)
{
    return (v < count && table[v] != NULL) ? table[v] : "?";
}
#define NAME_OF(table, v)   table_name((table), sizeof(table) / sizeof((table)[0]), (uint32_t)(v))

static const char *yes_no(uint8_t v)
{
    return v ? "yes" : "no";
}

/* -------------------------------------------------------------------------- */
/* Messages out (owner-task pattern: never call into another task's module)   */
/* -------------------------------------------------------------------------- */
/* Same as tony_ui.c: put the command, then wake Tom with TOM_CMD_FLAG. */
static void send_tom(TomCmdType_t type, uint8_t value)
{
    TomCmd_t c = { .type = type, .value = value };
    (void)App_RTOS_Put(tomCmdQueue, &c, 10U, &g_rtos_dropped.tom_cmd);
    (void)osThreadFlagsSet(TomTaskHandle, TOM_CMD_FLAG);
}

/* Stop the Speaker page's test pattern and give Tom his previous source
 * back: Jack's playback if a file is playing, at the block rate Tom had
 * (TOM_SRC_RATE_KEEP: 32 kHz for a recording, 48 kHz for an effect file;
 * only Jack knows which). A paused file gets its SOURCE_PLAYBACK from Jack
 * on resume, and with nothing playing the stopped (silent) output is what
 * was there before. */
static void pattern_stop(const StorageStatusMsg_t *sto)
{
    if (s_pattern_item == DBG_NONE) return;
    send_tom(TOM_CMD_STOP, 0U);
    if (sto->playing == JACK_PLAY_PLAYING) send_tom(TOM_CMD_SOURCE_PLAYBACK, (uint8_t)TOM_SRC_RATE_KEEP);
    s_pattern_item = DBG_NONE;
    s_dirty = 1U;
}

/* Speaker page, encoder push or PLAY. A tune plays once by itself (Tom
 * queues it behind one that is still playing); a test pattern plays until
 * it is pushed again, REC, or the page is left. */
static void speaker_play_stop(uint8_t item, const StorageStatusMsg_t *sto)
{
    if (debug_speaker_is_tune(item)) {
        send_tom(TOM_CMD_PLAY_TUNE, (uint8_t)((uint8_t)TOM_TUNE_STARTUP + debug_speaker_tune_index(item)));
        s_tune_item = item;
    } else if (debug_speaker_pattern_index(item) != DEBUG_INDEX_NONE) {
        if (item == s_pattern_item) {
            pattern_stop(sto);                  /* the playing one again: stop it */
            return;
        }
        send_tom(TOM_CMD_TEST_PATTERN,
                 (uint8_t)((uint8_t)TOM_TEST_SWEEP_100 + debug_speaker_pattern_index(item)));
        s_pattern_item = item;
    } else {
        return;                                 /* not a Speaker item */
    }
    s_dirty = 1U;
}

/* Faults page, encoder push. */
static void fault_inject(uint8_t item)
{
    uint8_t  soc  = 0U;
    uint16_t secs = 0U;
    uint8_t  ok   = 1U;

    switch (debug_fault_item_action(item, &soc, &secs)) {
        case DEBUG_FAULT_ACT_STORAGE:
            /* Raised by TonyTask itself: it comes back through faultQueue
             * on the next loop and opens the fault screen over this page
             * as "Storage (simulated)". */
            App_RTOS_RaiseFault((uint8_t)FAULT_SRC_STORAGE,
                                (uint8_t)(FAULT_SD_REMOVED | FAULT_CODE_SIMULATED),
                                "SD card removed", "Recording stopped");
            break;

        case DEBUG_FAULT_ACT_SOC_OVERRIDE:
        case DEBUG_FAULT_ACT_CLEAR_OVERRIDE: {
            /* BrendonTask owns the gauge: it reports this SOC instead of the
             * measured one (seconds 0 = clear), so the real low / critical
             * alarms, lockout, beep, tune and status bar all run. */
            BrendonCmd_t c = { .type = BRENDON_CMD_SOC_OVERRIDE, .soc_pct = soc, .seconds = secs };
            ok = (App_RTOS_Put(brendonCmdQueue, &c, 10U, &g_rtos_dropped.brendon_cmd) == osOK) ? 1U : 0U;
            break;
        }

        default:
            return;                             /* not a Faults item */
    }
    s_sent_item = item;
    s_sent_ok   = ok;
    s_dirty     = 1U;
}

/* -------------------------------------------------------------------------- */
/* Rows                                                                        */
/* -------------------------------------------------------------------------- */
/* FNV-1a over the row text and its colour. A different hash means the row
 * must be drawn again. (Two different texts with the same hash would only
 * leave that row stale until its next change.) FNV-1a is a small, standard
 * 32-bit hash: start from a fixed number, then for each byte XOR it in and
 * multiply by a fixed prime, so a changed letter almost always changes it. */
static uint32_t row_hash(const char *text, uint16_t colour)
{
    uint32_t h = 2166136261U;
    while (*text != '\0') {
        h ^= (uint8_t)*text++;
        h *= 16777619U;
    }
    h ^= colour;
    h *= 16777619U;
    return h;
}

/* Send the row built in s_row to the panel if it changed. It is padded with
 * spaces to the full 40 characters, so a shorter text overwrites all of the
 * old one. Straight after the full-screen fill only the text itself is
 * drawn: the rest of the row is black already.
 *
 * A whole page takes ~0.45 s on the blocking SPI1 path. A fault that arrives
 * meanwhile must not wait for the end of it (PD2 IR6: fault screen within
 * 500 ms; PD2 = the team's Prototype Design 2, the system requirements,
 * and IR6 is a requirement number in it), so a whole-page draw checks
 * faultQueue before every row and stops
 * once something is waiting. TonyDebug_Render then leaves the page marked
 * "not drawn": the next loop takes the fault off the queue (and draws the
 * fault screen for it), and the page is drawn whole again after that. */
static void emit_row(uint16_t colour)
{
    if (s_row_n >= DBG_ROWS) return;            /* a page never has more than 20 rows */
    uint8_t r   = s_row_n++;
    if (s_full && !s_abort && osMessageQueueGetCount(faultQueue) != 0U) s_abort = 1U;
    if (s_abort) return;
    size_t  len = strlen(s_row);
    memset(&s_row[len], ' ', DBG_COLS - len);
    s_row[DBG_COLS] = '\0';

    uint32_t h = row_hash(s_row, colour);
    if (!s_full && h == s_row_hash[r]) return;  /* unchanged: nothing to draw */
    s_row_hash[r] = h;

    if (s_full) {
        if (len == 0U) return;                  /* an empty row on a black screen */
        s_row[len] = '\0';
    }
    ILI9341_Draw_Text(s_row, DBG_X, (uint16_t)(DBG_Y0 + r * DBG_DY), colour, 1U, BLACK);
}

/* printf into the next row (cut to 40 characters). The format attribute
 * lets the compiler check every row's arguments. */
static void row(uint16_t colour, const char *fmt, ...) __attribute__((format(printf, 2, 3)));
static void row(uint16_t colour, const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    (void)vsnprintf(s_row, sizeof(s_row), fmt, ap);
    va_end(ap);
    emit_row(colour);
}

static void blank_row(void)
{
    s_row[0] = '\0';
    emit_row(DBG_TEXT_COLOUR);
}

/* -------------------------------------------------------------------------- */
/* Pages (the title row is drawn by TonyDebug_Render)                          */
/* -------------------------------------------------------------------------- */
/* Stack bytes, or "-" for a task that was not created (APP_RTOS_STACK_UNKNOWN:
 * never expected, every task is created at boot, but cheap to keep). */
static const char *stack_text(uint32_t bytes, char *buf, size_t len)
{
    if (bytes == APP_RTOS_STACK_UNKNOWN) return "-";
    (void)snprintf(buf, len, "%lu", (unsigned long)bytes);
    return buf;
}

static uint8_t stack_low(uint32_t bytes)
{
    return (bytes != APP_RTOS_STACK_UNKNOWN && bytes < DBG_LOW_STACK_B) ? 1U : 0U;
}

/* App_RTOS_TaskName() without its "Task" ending ("JackStorageTask" ->
 * "JackStorage", at most 11 characters), so two tasks and their stacks fit
 * one 40-column row. */
static const char *task_short(uint32_t i, char buf[12])
{
    const char *name = App_RTOS_TaskName(i);
    size_t      len  = strlen(name);
    if (len > 4U && strcmp(&name[len - 4U], "Task") == 0) len -= 4U;
    if (len > 11U) len = 11U;
    memcpy(buf, name, len);
    buf[len] = '\0';
    return buf;
}

/* 1 System: App_RTOS_GetStats(): the build, uptime, heap, every dropped-
 * message counter, the audio deadline counters and the stack headroom of
 * the six tasks. 17 rows with the title; the last 3 stay blank. */
static void page_system(void)
{
    App_RTOS_GetStats(&s_stats);
    const AppRtosDropped_t *d = &s_stats.dropped;
    uint32_t up_s = s_stats.uptime_ms / 1000U;

    row(DBG_TEXT_COLOUR, "Build   %s", App_RTOS_BuildString());
    row(DBG_TEXT_COLOUR, "Uptime  %lu:%02lu:%02lu", (unsigned long)(up_s / 3600U),
        (unsigned long)((up_s / 60U) % 60U), (unsigned long)(up_s % 60U));
    row(DBG_TEXT_COLOUR, "Heap B  free %lu min %lu of %lu",
        (unsigned long)s_stats.heap_free, (unsigned long)s_stats.heap_min_free,
        (unsigned long)s_stats.heap_total);
    /* The drop counters two to a row, in AppRtosDropped_t's order, the first
     * in a 10-digit column (the most a uint32_t has): 39 characters at most.
     * fx (FxRenderTask's two queues) is never expected to drop: at most one
     * request is out. */
    row(DBG_TEXT_COLOUR, "Dropped jack %-10lu tom  %lu",
        (unsigned long)d->jack_cmd, (unsigned long)d->tom_cmd);
    row(DBG_TEXT_COLOUR, "        req  %-10lu bat  %lu",
        (unsigned long)d->storage_req, (unsigned long)d->battery);
    row(DBG_TEXT_COLOUR, "        sts  %-10lu pcm  %lu",
        (unsigned long)d->storage_status, (unsigned long)d->pcm_frame);
    row(DBG_TEXT_COLOUR, "        blk  %-10lu flt  %lu",
        (unsigned long)d->audio_block, (unsigned long)d->fault);
    row(DBG_TEXT_COLOUR, "        bcmd %-10lu pwr  %lu",
        (unsigned long)d->brendon_cmd, (unsigned long)d->power_debug);
    row(DBG_TEXT_COLOUR, "        fx   %lu", (unsigned long)d->fx_render);
    /* One counter per row: two of them with their labels can need more than
     * the 40 columns, and a row longer than that is silently cut. underruns
     * alone counts every 4 ms half Tom had no playback block for. */
    row(DBG_TEXT_COLOUR, "Audio   jackMissed %lu", (unsigned long)s_stats.jack_missed);
    row(DBG_TEXT_COLOUR, "        tomMissed %lu", (unsigned long)s_stats.tom_missed);
    row(DBG_TEXT_COLOUR, "        underruns %lu", (unsigned long)s_stats.tom_underruns);
    row(DBG_HINT_COLOUR, "Stack free, lowest ever (bytes):");
    /* Two tasks per row: the six tasks take three rows. With an odd number
     * of tasks the last row would have one. */
    for (uint32_t i = 0U; i < APP_RTOS_TASK_COUNT; i += 2U) {
        char na[12], nb[12], a[12], b[12];
        uint32_t sa = s_stats.stack_free[i];
        if (i + 1U >= APP_RTOS_TASK_COUNT) {
            row(stack_low(sa) ? DBG_WARN_COLOUR : DBG_TEXT_COLOUR, "  %-11s %5s",
                task_short(i, na), stack_text(sa, a, sizeof(a)));
            break;
        }
        uint32_t sb = s_stats.stack_free[i + 1U];
        row((stack_low(sa) || stack_low(sb)) ? DBG_WARN_COLOUR : DBG_TEXT_COLOUR,
            "  %-11s %5s   %-11s %5s",
            task_short(i, na), stack_text(sa, a, sizeof(a)),
            task_short(i + 1U, nb), stack_text(sb, b, sizeof(b)));
    }
}

/* The effect file Jack is making now, for page 2: "FX job  REC05.WAV Echo
 * 40%" (widest "FX job  ABCDEFGH.WAV Pitch Down 100%", 36 columns), or
 * "FX job  none". */
static void fx_job_row(const StorageStatusMsg_t *st)
{
    if (st->fx_job_effect == (uint8_t)UI_EFFECT_NONE || st->fx_job_name[0] == '\0') {
        row(DBG_TEXT_COLOUR, "FX job  none");
        return;
    }
    row(DBG_TEXT_COLOUR, "FX job  %.12s %s %u%%", st->fx_job_name,
        ui_effect_name((ui_effect_t)st->fx_job_effect), (unsigned)st->fx_job_pct);
}

/* 2 Storage: Jack's StorageStatusMsg_t. */
static void page_storage(const StorageStatusMsg_t *st)
{
    const char *now = st->recording ? "recording" :
                      (st->playing == JACK_PLAY_PLAYING) ? "playing" :
                      (st->playing == JACK_PLAY_PAUSED) ? "paused" :
                      (st->playing == JACK_PLAY_PREPARING) ? "preparing" : "idle";
    /* bus_width / total_kb are 0 until Jack has mounted the card (and
     * measured it): say which of the two it is. */
    const char *unknown = st->mounted ? "unknown" : "unknown (not mounted)";

    row(DBG_TEXT_COLOUR, "Card    %s  mounted %s  USB-MSC %s",
        yes_no(st->card_present), yes_no(st->mounted), yes_no(st->msc_mode));
    if (st->bus_width == 0U) {
        row(DBG_TEXT_COLOUR, "Bus     %s", unknown);
    } else {
        row(DBG_TEXT_COLOUR, "Bus     %u-bit SDIO", (unsigned)st->bus_width);
    }
    /* Two rows either way, so the rows under them never move. */
    if (st->total_kb == 0U) {
        row(DBG_TEXT_COLOUR, "Space   %s", unknown);
        blank_row();
    } else {
        uint32_t free_kb = (st->free_kb <= st->total_kb) ? st->free_kb : st->total_kb;
        row(DBG_TEXT_COLOUR, "Space   used %lu MB of %lu MB",
            (unsigned long)((st->total_kb - free_kb) / 1024U), (unsigned long)(st->total_kb / 1024U));
        row(DBG_TEXT_COLOUR, "        free %lu MB", (unsigned long)(free_kb / 1024U));
    }
    row(DBG_TEXT_COLOUR, "Files   %u WAV, card %u %% used",
        (unsigned)st->file_count, (unsigned)st->percent_used);
    row(DBG_TEXT_COLOUR, "Status  %.15s", st->status_text);
    row(DBG_TEXT_COLOUR, "        record %s   play %s",
        st->record_enabled ? "ok" : "off", st->play_enabled ? "ok" : "off");
    row(st->last_result ? DBG_WARN_COLOUR : DBG_TEXT_COLOUR, "Last error  %s",
        NAME_OF(s_storage_results, st->last_result));
    row(DBG_TEXT_COLOUR, "Now     %s %.12s", now, st->current_name);
    fx_job_row(st);
    blank_row();
    row(DBG_HINT_COLOUR, "Jack is asked for status once a second");
}

/* "23.4 C" from tenths of a degree; INT16_MIN = the gauge did not say. */
static void temp_text(int16_t dC, char *buf, size_t len)
{
    if (dC == INT16_MIN) {
        (void)snprintf(buf, len, "unknown");
        return;
    }
    int32_t  t = dC;
    uint32_t a = (uint32_t)((t < 0) ? -t : t);
    (void)snprintf(buf, len, "%s%lu.%lu C", (t < 0) ? "-" : "",
                   (unsigned long)(a / 10U), (unsigned long)(a % 10U));
}

static uint16_t alarm_colour(const PowerDebugMsg_t *p)
{
    return (p->lockout || p->critical) ? DBG_WARN_COLOUR : (p->low ? DBG_LOW_COLOUR : DBG_TEXT_COLOUR);
}

/* 3 Battery / power: BrendonTask's PowerDebugMsg_t, and from his battery
 * message (ui: tony_ui.c's copy) the current now, its 2-minute average and
 * the firmware's time estimates, the ones the header and the Battery screen
 * show (in their steps), so they can be compared with the gauge's own slow
 * average and times. 15 rows with the title. Widest rows (40 columns), from
 * the type limits:
 *   "Voltage 65535 mV   gauge avg -32768 mA"   38
 *   "Current now -32768 mA  2m avg -32768 mA"  39
 *   "Time    est   empty --:--  full --:--"    37 (ui_format_hhmm: always 5)
 *   "        gauge empty --:--  full --:--"    37 */
static void page_power(const ui_state_t *ui, uint32_t now)
{
    if (!s_pwr_valid) {
        row(DBG_HINT_COLOUR, "waiting for data");
        row(DBG_HINT_COLOUR, "(BrendonTask sends it once a second)");
        return;
    }
    const PowerDebugMsg_t *p = &s_pwr;
    char tte[6], ttf[6], est_tte[6], est_ttf[6], temp[16];
    ui_format_hhmm(p->tte_min, tte, sizeof(tte));                       /* the gauge's own */
    ui_format_hhmm(p->ttf_min, ttf, sizeof(ttf));
    ui_format_hhmm(ui->battery_tte_min, est_tte, sizeof(est_tte));      /* the firmware's */
    ui_format_hhmm(ui->battery_ttf_min, est_ttf, sizeof(est_ttf));
    temp_text(p->temp_dC, temp, sizeof(temp));

    row((p->gauge_present && p->valid) ? DBG_TEXT_COLOUR : DBG_WARN_COLOUR,
        "Gauge   %s, reading %s", p->gauge_present ? "found" : "NOT FOUND",
        p->valid ? "valid" : "INVALID");
    row(DBG_TEXT_COLOUR, "Voltage %u mV   gauge avg %+d mA",
        (unsigned)p->voltage_mV, (int)p->current_mA);
    row(DBG_TEXT_COLOUR, "Current now %+d mA  2m avg %+d mA",
        (int)ui->battery_ma_now, (int)ui->battery_ma_avg);
    if (p->soc_override) {
        row(DBG_CURSOR_COLOUR, "SOC     %u %%  override %u s left",
            (unsigned)p->soc_pct, (unsigned)p->override_left_s);
    } else {
        row(DBG_TEXT_COLOUR, "SOC     %u %%", (unsigned)p->soc_pct);
    }
    row(DBG_TEXT_COLOUR, "Time    est   empty %s  full %s", est_tte, est_ttf);
    row(DBG_TEXT_COLOUR, "        gauge empty %s  full %s", tte, ttf);
    row(DBG_TEXT_COLOUR, "Temp    %s", temp);
    /* Charger and PG: two rows here (one in landscape), both red on a
     * charger FAULT. */
    uint16_t chg = (p->charger_state == (uint8_t)CHARGER_STATE_FAULT) ? DBG_WARN_COLOUR : DBG_TEXT_COLOUR;
    row(chg, "Charger %s", NAME_OF(s_charger_states, p->charger_state));
    row(chg, "        PG (input power) %s", yes_no(p->power_good));
    row(DBG_TEXT_COLOUR, "USB     VBUS %s   MSC %s", yes_no(p->vbus), yes_no(p->msc_active));
    row(DBG_TEXT_COLOUR, "        stack %s%s", p->usb_running ? "on, " : "off",
        p->usb_running ? NAME_OF(s_usb_states, p->usb_state) : "");
    row(alarm_colour(p), "Alarms  low %s  crit %s  lockout %s",
        yes_no(p->low), yes_no(p->critical), yes_no(p->lockout));
    row(DBG_TEXT_COLOUR, "I2C1    %s", p->i2c_irq ? "interrupt + flag" : "blocking fallback");
    if ((now - s_pwr_rx_ms) >= DBG_STALE_MS) {
        row(DBG_WARN_COLOUR, "no update for %lu s", (unsigned long)((now - s_pwr_rx_ms) / 1000U));
    } else {
        blank_row();
    }
}

/* 4 Speaker test: 10 test patterns, then 3 tunes, then the hints under
 * them, the crossover's split among them (20 rows with the title, all the
 * screen holds). */
static void page_speaker(const ui_state_t *ui)
{
    for (uint8_t i = 0U; i < DEBUG_SPEAKER_ITEMS; i++) {
        uint8_t     cur  = (i == ui->debug_item) ? 1U : 0U;
        const char *mark = (i == s_pattern_item) ? "(playing)" :
                           (i == s_tune_item)    ? "(sent)"    : "";
        row(cur ? DBG_CURSOR_COLOUR : DBG_TEXT_COLOUR, "%c %-16s %s",
            cur ? '>' : ' ', debug_speaker_item_name(i), mark);
    }
    blank_row();
    row(DBG_HINT_COLOUR, "push/PLAY: play, stop");
    row(DBG_HINT_COLOUR, "REC: stop the pattern");
    row(DBG_HINT_COLOUR, "tunes play once");
    row(DBG_HINT_COLOUR, "L = tweeter >1.6 kHz, R = sub <1.6 kHz");
    if (ui->speaker_locked) {
        row(DBG_WARN_COLOUR, "BATTERY LOCKOUT: only warnings sound");
    } else {
        blank_row();
    }
}

/* 5 Fault injection: the 5 items, the last one sent, and the battery state
 * BrendonTask reports back, so an override can be seen taking effect. */
static void page_faults(const ui_state_t *ui)
{
    for (uint8_t i = 0U; i < DEBUG_FAULT_ITEMS; i++) {
        uint8_t  cur  = (i == ui->debug_item) ? 1U : 0U;
        uint16_t col  = cur ? DBG_CURSOR_COLOUR : DBG_TEXT_COLOUR;
        uint8_t  soc  = 0U;
        uint16_t secs = 0U;
        debug_fault_action_t act = debug_fault_item_action(i, &soc, &secs);

        if (act == DEBUG_FAULT_ACT_SOC_OVERRIDE) {
            row(col, "%c %-16s SOC %u %% for %u s", cur ? '>' : ' ',
                debug_fault_item_name(i), (unsigned)soc, (unsigned)secs);
        } else {
            row(col, "%c %-16s %s", cur ? '>' : ' ', debug_fault_item_name(i),
                (act == DEBUG_FAULT_ACT_STORAGE) ? "fault screen (sim)" : "back to the real SOC");
        }
    }
    blank_row();
    row(DBG_HINT_COLOUR, "push = inject");
    if (s_sent_item == DBG_NONE) {
        blank_row();
    } else {
        row(s_sent_ok ? DBG_OK_COLOUR : DBG_WARN_COLOUR, "%s %s",
            s_sent_ok ? "sent:" : "NOT sent (queue full):", debug_fault_item_name(s_sent_item));
    }
    if (!s_pwr_valid) {
        row(DBG_HINT_COLOUR, "Battery: waiting for data");
    } else {
        /* Without a gauge (or a valid reading) the SOC is not a gauge
         * reading, and BrendonTask refuses the overrides without a gauge:
         * say so here, where the injection seems to do nothing. */
        if (s_pwr.soc_override) {
            row(DBG_CURSOR_COLOUR, "Battery SOC %u %% override %u s left",
                (unsigned)s_pwr.soc_pct, (unsigned)s_pwr.override_left_s);
        } else if (!s_pwr.gauge_present) {
            row(DBG_WARN_COLOUR, "Battery: no gauge - overrides refused");
        } else if (!s_pwr.valid) {
            row(DBG_WARN_COLOUR, "Battery: gauge reading invalid");
        } else {
            row(DBG_TEXT_COLOUR, "Battery SOC %u %% from the gauge", (unsigned)s_pwr.soc_pct);
        }
        row(alarm_colour(&s_pwr), "Alarms  low %s  crit %s  lockout %s",
            yes_no(s_pwr.low), yes_no(s_pwr.critical), yes_no(s_pwr.lockout));
    }
}

/* -------------------------------------------------------------------------- */
/* Public API                                                                  */
/* -------------------------------------------------------------------------- */
void TonyDebug_DrainPower(void)
{
    PowerDebugMsg_t m;
    if (osMessageQueueGet(powerDebugQueue, &m, NULL, 0U) == osOK) {
        s_pwr       = m;
        s_pwr_valid = 1U;
        s_pwr_rx_ms = osKernelGetTickCount();
    }
}

bool TonyDebug_PowerSnapshot(PowerDebugMsg_t *out)
{
    if (out == NULL || !s_pwr_valid || (osKernelGetTickCount() - s_pwr_rx_ms) >= DBG_STALE_MS) {
        return false;                           /* none yet, or BrendonTask has gone quiet */
    }
    *out = s_pwr;
    return true;
}

void TonyDebug_OnEvent(ui_event_t ev, const ui_state_t *ui, const StorageStatusMsg_t *sto)
{
    if (ui->screen != UI_SCREEN_DEBUG) return;  /* BACK has left: TonyDebug_Update tidies up */

    if (ui->debug_page == DEBUG_PAGE_SPEAKER) {
        if (ev == EVENT_MUTE_TOGGLE || ev == EVENT_BTN_PLAYPAUSE) {
            speaker_play_stop(ui->debug_item, sto);
        } else if (ev == EVENT_BTN_RECORD) {
            pattern_stop(sto);
        }
    } else if (ui->debug_page == DEBUG_PAGE_FAULTS) {
        if (ev == EVENT_MUTE_TOGGLE) {
            fault_inject(ui->debug_item);
        }
    }
    /* The three information pages have no actions. */
}

void TonyDebug_Update(const ui_state_t *ui, const StorageStatusMsg_t *sto)
{
    if (s_pattern_item != DBG_NONE &&
        !(ui->screen == UI_SCREEN_DEBUG && ui->debug_page == DEBUG_PAGE_SPEAKER)) {
        pattern_stop(sto);
    }
}

void TonyDebug_Render(const ui_state_t *ui, const StorageStatusMsg_t *sto, uint8_t full)
{
    uint32_t now  = osKernelGetTickCount();
    uint8_t  page = ui->debug_page;

    if (page != s_drawn_page) full = 1U;        /* another page: start from a clean panel */
    if (!full && !s_dirty && ui->debug_item == s_drawn_item &&
        (int32_t)(now - s_next_pass_ms) < 0) {
        return;                                 /* nothing new, and the 1 s refresh is not due */
    }
    if (full && osMessageQueueGetCount(faultQueue) != 0U) {
        s_drawn_page = 0xFFU;                   /* a fault first (see emit_row); the page after it */
        return;
    }
    if (full) ILI9341_Fill_Screen(BLACK);
    s_full  = full;
    s_abort = 0U;
    s_row_n = 0U;

    row(DBG_TITLE_COLOUR, "DEBUG %u/%u %s   BACK = exit",
        (unsigned)page + 1U, (unsigned)DEBUG_PAGE_COUNT, debug_page_title(page));
    switch (page) {
        case DEBUG_PAGE_STORAGE: page_storage(sto);   break;
        case DEBUG_PAGE_POWER:   page_power(ui, now); break;
        case DEBUG_PAGE_SPEAKER: page_speaker(ui);    break;
        case DEBUG_PAGE_FAULTS:  page_faults(ui);     break;
        default:                 page_system();       break;
    }
    while (s_row_n < DBG_ROWS) blank_row();     /* rows this page leaves empty may hold old text */
    if (s_abort) {
        s_drawn_page = 0xFFU;                   /* stopped for a fault: draw it whole next time */
        return;
    }

    s_drawn_page   = page;
    s_drawn_item   = ui->debug_item;
    s_dirty        = 0U;
    s_next_pass_ms = now + DBG_REFRESH_MS;
}
